using System.Collections.Generic;
using System.IO;
using System.Linq;
using YamlDotNet.Serialization;
using YamlDotNet.Serialization.NamingConventions;

namespace MyApp.Evaluation;

public sealed class ScenarioLoader
{
    public static List<EvaluationScenario> Load(string path = "evaluation.yml")
    {
        var yaml = File.ReadAllText(path);
        var deserializer = new DeserializerBuilder()
            .WithNamingConvention(UnderscoredNamingConvention.Instance)
            .Build();

        var doc = deserializer.Deserialize<EvaluationDocument>(yaml);
        return doc.Scenarios;
    }
}

public sealed class EvaluationDocument
{
    public List<EvaluationScenario> Scenarios { get; set; } = [];
}

public sealed class EvaluationScenario
{
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<ScenarioTurn> Turns { get; set; } = [];
    public List<string> Evaluators { get; set; } = [];
}

public sealed class ScenarioTurn
{
    public string Role { get; set; } = string.Empty;
    public string Content { get; set; } = string.Empty;
}

using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.DependencyInjection;
using Xunit;

namespace MyApp.Evaluation;

public class EvaluationTests
{
    [Fact]
    public async Task RunAllScenarios()
    {
        var scenarios = ScenarioLoader.Load();
        Assert.NotEmpty(scenarios);

        await using var appHost = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        await appHost.BuildAsync();
        var app = await appHost.StartAsync();

        var chatClient = app.Services.GetRequiredService<IChatClient>();
        var results = new List<ScenarioResult>();

        foreach (var scenario in scenarios)
        {
            var result = await EvaluateScenarioAsync(chatClient, scenario);
            results.Add(result);
        }

        // Assert all scenarios passed their evaluators.
        foreach (var result in results)
        {
            Assert.True(
                result.Passed,
                $"Scenario '{result.ScenarioName}' failed: {result.FailureReason}");
        }
    }

    [Theory]
    [MemberData(nameof(GetScenarioNames))]
    public async Task EvaluateScenario(string scenarioName)
    {
        var scenarios = ScenarioLoader.Load();
        var scenario = scenarios.First(s => s.Name == scenarioName);

        await using var appHost = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        await appHost.BuildAsync();
        var app = await appHost.StartAsync();

        var chatClient = app.Services.GetRequiredService<IChatClient>();
        var result = await EvaluateScenarioAsync(chatClient, scenario);

        Assert.True(
            result.Passed,
            $"Scenario '{result.ScenarioName}' failed: {result.FailureReason}");
    }

    public static IEnumerable<object[]> GetScenarioNames()
    {
        var scenarios = ScenarioLoader.Load();
        return scenarios.Select(s => new object[] { s.Name });
    }

    private static async Task<ScenarioResult> EvaluateScenarioAsync(
        IChatClient chatClient,
        EvaluationScenario scenario)
    {
        var messages = new List<ChatMessage>();

        // Build the conversation turns.
        ChatMessage? lastResponse = null;
        foreach (var turn in scenario.Turns)
        {
            messages.Add(new ChatMessage(
                turn.Role == "user" ? ChatRole.User : ChatRole.Assistant,
                turn.Content));

            var response = await chatClient.GetResponseAsync(messages);
            lastResponse = new ChatMessage(ChatRole.Assistant, response.Text);
            messages.Add(lastResponse);
        }

        if (lastResponse is null)
        {
            return new ScenarioResult(scenario.Name, false, "No response generated.");
        }

        // Run the requested evaluators.
        var evaluators = CreateEvaluators(scenario.Evaluators, chatClient);
        var failures = new List<string>();

        foreach (var evaluator in evaluators)
        {
            var evalResult = await evaluator.EvaluateAsync(messages, lastResponse);
            if (!evalResult.IsSuccessful)
            {
                failures.Add($"{evaluator.GetType().Name}: {evalResult.Reason}");
            }
        }

        return failures.Count == 0
            ? new ScenarioResult(scenario.Name, true, null)
            : new ScenarioResult(scenario.Name, false, string.Join("; ", failures));
    }

    private static List<IEvaluator> CreateEvaluators(
        List<string> evaluatorNames,
        IChatClient chatClient)
    {
        var evaluators = new List<IEvaluator>();

        foreach (var name in evaluatorNames)
        {
            IEvaluator? evaluator = name.ToLowerInvariant() switch
            {
                "relevance" => new RelevanceEvaluator(chatClient),
                "coherence" => new CoherenceEvaluator(chatClient),
                "fluency" => new FluencyEvaluator(chatClient),
                "groundedness" => new GroundednessEvaluator(chatClient),
                _ => null,
            };

            if (evaluator is not null)
            {
                evaluators.Add(evaluator);
            }
        }

        return evaluators;
    }
}

public sealed record ScenarioResult(string ScenarioName, bool Passed, string? FailureReason);

public interface IEvaluator
{
    Task<EvaluationResult> EvaluateAsync(
        IReadOnlyList<ChatMessage> conversationHistory,
        ChatMessage response);
}

public sealed record EvaluationResult(bool IsSuccessful, string? Reason);

public sealed class RelevanceEvaluator(IChatClient chatClient) : IEvaluator
{
    public async Task<EvaluationResult> EvaluateAsync(
        IReadOnlyList<ChatMessage> conversationHistory,
        ChatMessage response)
    {
        var prompt = $"""
            Evaluate the relevance of the following response to the conversation.
            Conversation: {string.Join("\n", conversationHistory.Select(m => $"{m.Role}: {m.Text}"))}
            Response: {response.Text}
            Is the response relevant? Answer YES or NO followed by a brief reason.
            """;

        var result = await chatClient.GetResponseAsync(prompt);
        var passed = result.Text?.TrimStart().StartsWith("YES", System.StringComparison.OrdinalIgnoreCase) ?? false;
        return new EvaluationResult(passed, passed ? null : result.Text);
    }
}

public sealed class CoherenceEvaluator(IChatClient chatClient) : IEvaluator
{
    public async Task<EvaluationResult> EvaluateAsync(
        IReadOnlyList<ChatMessage> conversationHistory,
        ChatMessage response)
    {
        var prompt = $"""
            Evaluate the coherence of the following response.
            Response: {response.Text}
            Is the response coherent and well-structured? Answer YES or NO followed by a brief reason.
            """;

        var result = await chatClient.GetResponseAsync(prompt);
        var passed = result.Text?.TrimStart().StartsWith("YES", System.StringComparison.OrdinalIgnoreCase) ?? false;
        return new EvaluationResult(passed, passed ? null : result.Text);
    }
}

public sealed class FluencyEvaluator(IChatClient chatClient) : IEvaluator
{
    public async Task<EvaluationResult> EvaluateAsync(
        IReadOnlyList<ChatMessage> conversationHistory,
        ChatMessage response)
    {
        var prompt = $"""
            Evaluate the fluency of the following response.
            Response: {response.Text}
            Is the response fluent and grammatically correct? Answer YES or NO followed by a brief reason.
            """;

        var result = await chatClient.GetResponseAsync(prompt);
        var passed = result.Text?.TrimStart().StartsWith("YES", System.StringComparison.OrdinalIgnoreCase) ?? false;
        return new EvaluationResult(passed, passed ? null : result.Text);
    }
}

public sealed class GroundednessEvaluator(IChatClient chatClient) : IEvaluator
{
    public async Task<EvaluationResult> EvaluateAsync(
        IReadOnlyList<ChatMessage> conversationHistory,
        ChatMessage response)
    {
        var prompt = $"""
            Evaluate whether the following response is grounded in facts.
            Conversation: {string.Join("\n", conversationHistory.Select(m => $"{m.Role}: {m.Text}"))}
            Response: {response.Text}
            Is the response factually grounded and not hallucinating? Answer YES or NO followed by a brief reason.
            """;

        var result = await chatClient.GetResponseAsync(prompt);
        var passed = result.Text?.TrimStart().StartsWith("YES", System.StringComparison.OrdinalIgnoreCase) ?? false;
        return new EvaluationResult(passed, passed ? null : result.Text);
    }
}

